SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, method, COUNT(*) AS num_rows, SUM(amount) FILTER (WHERE status = 'SUCCESS') AS success_total_amount, SORT_ARRAY(COLLECT_SET(status)) AS status_list, STDDEV_SAMP(amount) AS amount_stddev, COUNT(DISTINCT id) AS distinct_ids, GROUPING(DATE_TRUNC('WEEK', paid_at)) AS grouping_level FROM payments GROUP BY ROLLUP (DATE_TRUNC('WEEK', paid_at), method) HAVING success_total_amount > 0
